import numpy as np

def compute_psnr(original_img: np.ndarray, compressed_img: np.ndarray) -> float:
    mse = np.mean((original_img.astype(float) - compressed_img.astype(float)) ** 2)
    if mse == 0:
        return 100.0
    max_i = 255.0
    psnr = 10.0 * np.log10((max_i ** 2) / mse)
    return round(float(psnr), 2)
